from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

import heapq
from itertools import product, combinations
from collections import Counter


def _route(data, exact, minimum):
    required = data.get("required", [])
    full = (1 << len(required)) - 1
    visit = {node: sum(1 << i for i, name in enumerate(required) if name == node)
             for node in range(data["n"])}
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source, target = data["source"], data["target"]
    budget, start = data["coupons"], data["start"]
    initial = (source, visit[source], 0)
    distance = {initial: start}
    queue = [(start, initial)]
    while queue:
        time, state = heapq.heappop(queue)
        if distance.get(state) != time:
            continue
        node, mask, used = state
        if node == target and mask == full and (not exact or used == budget):
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], used)]
            if used < budget:
                duration = max(minimum, edge["duration"] - edge.get("discount", 0))
                options.append((duration, used + 1))
            for duration, next_used in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                nxt = (edge["v"], mask | visit[edge["v"]], next_used)
                if arrival < distance.get(nxt, float("inf")):
                    distance[nxt] = arrival
                    heapq.heappush(queue, (arrival, nxt))
    return {"arrival": None}


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for pos, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = (sequence, event.get("revision", 0), pos)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    half_up = data["rounding"] == "half_up"

    def rounded(n, d=10000):
        return (2 * n + d) // (2 * d) if half_up else n // d

    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(raw * event.get("tax_bp", 0))
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        account = event.get("account", "default")
        currency = event.get("currency", "USD")
        key = account + "|" + currency
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    roots = data["roots"]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    choices = []
    for name in names:
        choices.append([None] + [row for row in packages[name]
                                  if row["version"] not in blocked.get(name, [])])

    best_key = None
    best = None
    for assignment in product(*choices):
        rows = {name: row for name, row in zip(names, assignment) if row is not None}
        versions = {name: row["version"] for name, row in rows.items()}
        if any(name not in versions or not bounds[0] <= versions[name] <= bounds[1]
               for name, bounds in roots.items()):
            continue
        if any(name in versions and versions[name] != version
               for name, version in pins.items()):
            continue

        graph = {}
        valid = True
        for name, row in rows.items():
            deps = []
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                if other not in versions or not dep["min"] <= versions[other] <= dep["max"]:
                    valid = False
                    break
                deps.append(other)
            graph[name] = deps
            if not valid:
                break
        if not valid:
            continue

        reachable, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in reachable:
                return True
            active.add(name)
            for other in graph.get(name, []):
                if not visit(other):
                    return False
            active.remove(name)
            reachable.add(name)
            return True

        if any(not visit(name) for name in roots) or reachable != set(rows):
            continue
        key = tuple(versions.get(name, -1) for name in names)
        if best_key is None or key > best_key:
            best_key, best = key, versions
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def _jobs(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None

    if mandatory & blocked:
        return {"error": "impossible"}
    allowed_jobs = [job for job in jobs if job["id"] not in blocked]
    for subset in combinations(allowed_jobs, k):
        ids = sorted(job["id"] for job in subset)
        if not mandatory.issubset(ids):
            continue
        counts = Counter(job["group"] for job in subset)
        if any(not low <= counts[group] <= high
               for group, (low, high) in quotas.items()):
            continue

        active_ends = []
        feasible = True
        for job in sorted(subset, key=lambda item: (item["start"], item["end"])):
            active_ends = [end for end in active_ends if end > job["start"]]
            if len(active_ends) >= 2:
                feasible = False
                break
            active_ends.append(job["end"])
        if not feasible:
            continue
        value = sum(job["value"] for job in subset)
        if (best_value is None or value > best_value or
                (value == best_value and ids < best_ids)):
            best_value, best_ids = value, ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


SOLVERS = {
    "component_01": lambda d: _route(d, True, 2),
    "component_02": lambda d: _route(d, False, 1),
    "component_03": lambda d: _route(d, True, 1),
    "component_04": lambda d: _route(d, False, 2),
    "component_05": lambda d: _route(d, True, 2),
    "component_06": _ledger,
    "component_07": _dependencies,
    "component_08": _jobs,
}
